use std::sync::Arc;
use tokio::sync::RwLock;

use op_grpc_bridge::{grpc_server::run_grpc_server, schema_engine::SchemaEngine};
use op_identity::{schema_bridge::write_sled, IdentitySled};
use op_jsonrpc::nonnet::NonNetDb;
use op_network::ovsdb::OvsdbClient;
use op_state_store::{ChainConfig, EventChain};

// Static footprint matching the Xray config's X-Ghostbridge-Footprint header.
// When the Shuttle is deployed this will be written dynamically per WG session.
const STATIC_FOOTPRINT_HEX: &str =
    "d51501c285e50f44b63d2431494e5b6ae2c8b9057f00d91cc441b550680ab058";

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::from_default_env()
                .add_directive("op_grpc_bridge=info".parse()?)
                .add_directive("info".parse()?),
        )
        .init();

    // ── Write the Sled ────────────────────────────────────────────────────────
    // Decode the static footprint and write a valid IdentitySled to shm so the
    // ghostbridge interceptor can validate incoming requests immediately.
    let footprint_bytes =
        hex::decode(STATIC_FOOTPRINT_HEX).expect("STATIC_FOOTPRINT_HEX must be valid hex");
    let mut hashed_footprint = [0u8; 32];
    hashed_footprint.copy_from_slice(&footprint_bytes);

    let sled = IdentitySled {
        wireguard_pubkey: [0u8; 32], // populated by Shuttle when live WG session exists
        mutation_index: 0,
        is_valid: true,
        hashed_footprint,
    };
    write_sled(&sled)?;
    tracing::info!("Sled written to /dev/shm/plugin_schema.dat");

    // ── Build SchemaEngine ────────────────────────────────────────────────────
    let event_chain = Arc::new(RwLock::new(EventChain::new(ChainConfig::default())));
    let ovsdb = Arc::new(OvsdbClient::new());
    let nonnet = Arc::new(NonNetDb::new());
    let schema_engine = Arc::new(SchemaEngine::new(event_chain, ovsdb, nonnet));

    // ── Bind address ─────────────────────────────────────────────────────────
    // grpc-bridge veth host-end; Xray redirects to 10.200.0.2:50051.
    let addr: std::net::SocketAddr = std::env::var("GRPC_BIND")
        .unwrap_or_else(|_| "10.200.0.2:50051".to_string())
        .parse()
        .expect("GRPC_BIND must be a valid socket address");

    tracing::info!(%addr, "starting op-grpc-bridge");

    run_grpc_server(addr, schema_engine, None).await?;
    Ok(())
