async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    let bridge = env_or("BRIDGE", "ovsbr0");
    let uplink = env_or("UPLINK", "ens3");
    let uplink_ovs_type = env_or_compat("UPLINK_OVS_TYPE", "OVS_UPLINK_TYPE", "system");
    let af_xdp_mode = env_or("AF_XDP_MODE", "skb");
    let af_xdp_rxq = env_or("AF_XDP_RXQ", "2");
    let data_veth_host = env_or_compat("DATA_VETH_HOST", "VETH_HOST", "grpc-uplink");
    let data_veth_peer = env_or_compat("DATA_VETH_PEER", "VETH_PEER", "eth0");
    let of_veth_host = env_or("OF_VETH_HOST", "of-uplink0");
    let of_veth_peer = env_or("OF_VETH_PEER", "of-phys");
    let enable_of_veth = env_or("ENABLE_OF_VETH", "1") != "0";
    let xdp_obj = PathBuf::from(env_or("XDP_OBJ", "/usr/local/lib/op-xdp/xdp_steering.o"));
    let xdp_sec = env_or("XDP_SEC", "xdp");
    let xdp_mode = XdpMode::parse(&env_or("XDP_MODE", "generic"))?;
    let attach_xdp = env_or("ATTACH_XDP", "1") != "0";

    tracing::info!(
        %bridge, %uplink, %data_veth_host, %data_veth_peer, %of_veth_host, %of_veth_peer,
        xdp_obj = %xdp_obj.display(),
        %xdp_sec, ?xdp_mode, attach_xdp, enable_of_veth, %uplink_ovs_type,
        "op-ovsbr0-uplink starting"
    );

    let ovsdb = OvsdbClient::new();
    ovsdb
        .ensure_initialized()
        .await
        .context("OVSDB not reachable")?;

    // 1) Bridge must already exist (op-ovsbr0-setup runs first).
    if !ovsdb
        .bridge_exists(&bridge)
        .await
        .context("bridge_exists query")?
    {
        anyhow::bail!(
            "bridge {} not present in OVSDB — run op-ovsbr0-setup first",
            bridge
        );
    }
    tracing::info!(%bridge, "bridge present");

    // 2) Prepare uplink: flush v4 + link up. Errors on flush are tolerated
    //    (interface may already have nothing to flush).
    let _ = rtn::flush_addresses(&uplink).await;
    let _ = rtn::flush_default_routes_v4(&uplink).await;
    rtn::link_up(&uplink)
        .await
        .with_context(|| format!("link up {}", uplink))?;
    tracing::info!(%uplink, "uplink flushed and up");

    // 3) Attach uplink to bridge. AF_XDP mode is an OVSDB Interface type/options
    //    choice; it is separate from the libbpf XDP program attached below.
    let uplink_type = if uplink_ovs_type == "afxdp" {
        Some("afxdp")
    } else {
        None
    };
    ensure_bridge_port_with_type(&ovsdb, &bridge, &uplink, uplink_type).await?;
    if uplink_ovs_type == "afxdp" {
        ovsdb
            .set_interface_options(
                &uplink,
                &[
                    ("xdp-mode", af_xdp_mode.as_str()),
                    ("n_rxq", af_xdp_rxq.as_str()),
                ],
            )
            .await
            .with_context(|| format!("set AF_XDP options on {}", uplink))?;
        tracing::info!(%uplink, xdp_mode = %af_xdp_mode, n_rxq = %af_xdp_rxq, "AF_XDP uplink options applied");
    } else if uplink_ovs_type != "system" {
        tracing::warn!(%uplink_ovs_type, "unknown UPLINK_OVS_TYPE, using normal system port");
    }

    // 4) Data veth pair: The Sled/Shuttle gRPC data path.
    ensure_host_veth(&data_veth_host, &data_veth_peer).await?;

    // 5) OpenFlow veth pair: control plane stays distinct from data traffic.
    if enable_of_veth {
        ensure_host_veth(&of_veth_host, &of_veth_peer).await?;
    }

    // 6) Attach host-side veths to bridge.
    ensure_bridge_port(&ovsdb, &bridge, &data_veth_host).await?;
    if enable_of_veth {
        ensure_bridge_port(&ovsdb, &bridge, &of_veth_host).await?;
    }

    // 7) XDP attach on UPLINK and DATA_VETH_HOST. OpenFlow stays plain rtnetlink/OVS.
    if attach_xdp {
        if !xdp_obj.exists() {
            tracing::warn!(
                path = %xdp_obj.display(),
                "XDP_OBJ not present — skipping XDP attach (set ATTACH_XDP=0 to silence)"
            );
        } else {
            let loaded = xdp::load(&xdp_obj, &xdp_sec)
                .with_context(|| format!("load XDP ELF {}", xdp_obj.display()))?;
            loaded
                .attach(&uplink, xdp_mode)
                .with_context(|| format!("attach XDP to {}", uplink))?;
            tracing::info!(%uplink, ?xdp_mode, "XDP attached to uplink");
            loaded
                .attach(&data_veth_host, xdp_mode)
                .with_context(|| format!("attach XDP to {}", data_veth_host))?;
            tracing::info!(%data_veth_host, ?xdp_mode, "XDP attached to data veth host");
        }
    } else {
        tracing::info!("ATTACH_XDP=0, skipping XDP load/attach");
    }

    // 7) Bring the bridge itself up last.
    rtn::link_up(&bridge)
        .await
        .with_context(|| format!("link up {}", bridge))?;
    tracing::info!(%bridge, "bridge link up");

    tracing::info!("op-ovsbr0-uplink: done");
    Ok(())
}

