//! op-xdp-ct-setup — configure wg-xray container networking via rtnetlink.
//!
//! Enters the container's network namespace by PID and sets:
//!   - MAC address on CT_IF (to match host eth0 for XDP frame acceptance)
//!   - CT_IPV4/32 public IPv4 address on CT_IF
//!   - IPv4 link route to gateway + default IPv4 route
//!   - GRPC_ADDR/GRPC_PREFIX gRPC alias on CT_IF
//!   - OF_ADDR/OF_PREFIX OpenFlow control-plane address on OF_IF, when present
//!
//! IPv6 (CT_IPV6) is intentionally NOT set here — it belongs on host ens3.
//!
//! Usage: op-xdp-ct-setup <pid>
//! Env overrides: CT_IF, HOST_MAC, CT_IPV4, IPV4_PREFIX, IPV4_GW, GRPC_ADDR, GRPC_PREFIX,
//! OF_IF, OF_ADDR, OF_PREFIX

use anyhow::{Context, Result};
use op_network::netns::with_netns_pid;
use op_network::rtnetlink;
use std::net::Ipv4Addr;

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    let pid: u32 = std::env::args()
        .nth(1)
        .context("usage: op-xdp-ct-setup <pid>")?
        .parse()
        .context("pid must be a number")?;

    let ct_if = std::env::var("CT_IF").unwrap_or_else(|_| "eth0".into());
    let mac = std::env::var("HOST_MAC").unwrap_or_else(|_| "fa:16:3e:f1:71:d2".into());
    let ct_ipv4 = std::env::var("CT_IPV4").unwrap_or_else(|_| "148.113.204.83".into());
    let ipv4_prefix: u8 = std::env::var("IPV4_PREFIX")
        .unwrap_or_else(|_| "32".into())
        .parse()
        .unwrap_or(32);
    let ipv4_gw = std::env::var("IPV4_GW").unwrap_or_else(|_| "148.113.204.1".into());
    let grpc_addr = std::env::var("GRPC_ADDR").unwrap_or_else(|_| "10.200.0.1".into());
    let grpc_prefix: u8 = std::env::var("GRPC_PREFIX")
        .unwrap_or_else(|_| "30".into())
        .parse()
        .unwrap_or(30);
    let of_if = std::env::var("OF_IF").unwrap_or_else(|_| "of-phys".into());
    let of_addr = std::env::var("OF_ADDR").unwrap_or_else(|_| "10.210.0.1".into());
    let of_prefix: u8 = std::env::var("OF_PREFIX")
        .unwrap_or_else(|_| "30".into())
        .parse()
        .unwrap_or(30);

    println!("op-xdp-ct-setup: entering netns pid={}", pid);

    with_netns_pid(pid, move || {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()?;

        rt.block_on(async {
            // MAC — interface must be down to change MAC
            rtnetlink::link_down(&ct_if).await.ok();
            rtnetlink::set_mac_address(&ct_if, &mac)
                .await
                .with_context(|| format!("set MAC {} on {}", mac, ct_if))?;
            rtnetlink::link_up(&ct_if)
                .await
                .with_context(|| format!("link up {}", ct_if))?;
            println!("  MAC {} set on {}", mac, ct_if);

            // IPv4 public address
            rtnetlink::add_ipv4_address(&ct_if, &ct_ipv4, ipv4_prefix)
                .await
                .with_context(|| format!("add {}/{} to {}", ct_ipv4, ipv4_prefix, ct_if))?;
            println!("  {}/{} added to {}", ct_ipv4, ipv4_prefix, ct_if);

            // IPv4 link route (gateway reachable on-link)
            let gw_v4: Ipv4Addr = ipv4_gw.parse()?;
            rtnetlink::add_link_route_v4(&ct_if, gw_v4, 32)
                .await
                .with_context(|| format!("add link route {} on {}", ipv4_gw, ct_if))?;
            println!("  {} scope link on {}", ipv4_gw, ct_if);

            // IPv4 default route
            rtnetlink::add_default_route_v4(&ct_if, &ipv4_gw, 100)
                .await
                .with_context(|| format!("add default v4 via {}", ipv4_gw))?;
            println!("  default v4 via {}", ipv4_gw);

            // gRPC IPv4 alias
            rtnetlink::add_ipv4_address(&ct_if, &grpc_addr, grpc_prefix)
                .await
                .with_context(|| format!("add {}/{} to {}", grpc_addr, grpc_prefix, ct_if))?;
            println!("  {}/{} added to {}", grpc_addr, grpc_prefix, ct_if);

            if !of_if.is_empty() && rtnetlink::link_exists(&of_if).await? {
                rtnetlink::link_up(&of_if)
                    .await
                    .with_context(|| format!("link up {}", of_if))?;
                rtnetlink::add_ipv4_address(&of_if, &of_addr, of_prefix)
                    .await
                    .with_context(|| format!("add {}/{} to {}", of_addr, of_prefix, of_if))?;
                println!("  {}/{} added to {}", of_addr, of_prefix, of_if);
            } else if !of_if.is_empty() {
                println!("  OpenFlow interface {} not present, skipping", of_if);
            }

            println!("op-xdp-ct-setup: done");
            Ok(())
        })
    })
    .await
}

