//! OpenFlow 1.3 controller for ovsbr0
//!
//! Connects to OVS via unix socket or TCP (using `rovs-openflow::VConn`),
//! discovers port numbers from OVSDB, then installs intent flows from the
//! plugin schema JSON.
//!
//! Environment variables:
//!   OF_CONTROLLER_ADDRESS    connection address (default: unix:/var/run/openvswitch/ovsbr0.mgmt)
//!   OF_BRIDGE                bridge intent name (default: ovsbr0)
//!   OP_OPENFLOW_INTENT_DIR   directory with plugin intent JSON (default: /etc/op-network/openflow)
//!   OF_FLOW_PRIORITY         default priority when omitted in intent (default: 100)

use std::net::Ipv4Addr;
use std::path::PathBuf;

use anyhow::{Context, Result};
use op_network::{get_port_map_from_ovsdb, IntentFlow};
use rovs_openflow::{ActionList, Match, OutputPort, VConn};
use rovs_transport::Address;
use serde_json::Value;
use tracing::info;
use tracing_subscriber::EnvFilter;

fn sanitize_bridge_name(bridge: &str) -> String {
    bridge
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.') {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

fn intent_path_for_bridge(bridge: &str) -> PathBuf {
    let base = std::env::var("OP_OPENFLOW_INTENT_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|_| PathBuf::from("/etc/op-network/openflow"));
    base.join(format!("{}.json", sanitize_bridge_name(bridge)))
}

/// Parse intent JSON → Vec<IntentFlow>.
fn load_intent_flows(bridge: &str, default_priority: u16) -> Result<Vec<IntentFlow>> {
    let path = intent_path_for_bridge(bridge);
    let bytes = match std::fs::read(&path) {
        Ok(bytes) => bytes,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(err) => return Err(err).with_context(|| format!("read {}", path.display())),
    };

    let root: Value =
        serde_json::from_slice(&bytes).with_context(|| format!("parse {}", path.display()))?;
    let mut flows = Vec::new();

    for flow in root
        .get("flows")
        .and_then(|v| v.as_array())
        .into_iter()
        .flatten()
    {
        let mut intent = IntentFlow {
            priority: flow
                .get("priority")
                .and_then(|v| v.as_u64())
                .and_then(|v| u16::try_from(v).ok())
                .unwrap_or(default_priority),
            cookie: flow.get("cookie").and_then(|v| v.as_u64()).unwrap_or(0),
            idle_timeout: flow
                .get("idle_timeout")
                .and_then(|v| v.as_u64())
                .and_then(|v| u16::try_from(v).ok())
                .unwrap_or(0),
            hard_timeout: flow
                .get("hard_timeout")
                .and_then(|v| v.as_u64())
                .and_then(|v| u16::try_from(v).ok())
                .unwrap_or(0),
            table_id: flow
                .get("table")
                .and_then(|v| v.as_u64())
                .and_then(|v| u8::try_from(v).ok())
                .unwrap_or(0),
            ..Default::default()
        };

        // Parse match fields.
        if let Some(mf) = flow.get("match_fields").and_then(|v| v.as_object()) {
            intent.in_port = mf
                .get("in_port")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string());

            intent.eth_type = mf
                .get("dl_type")
                .and_then(|v| v.as_str())
                .and_then(parse_hex_u16);

            intent.ip_proto = mf
                .get("ip")
                .and_then(|v| v.as_str())
                .map(|_| 0x04) // "ip" keyword → eth_type 0x0800 handled below
                .or_else(|| mf.get("tcp").and_then(|v| v.as_str()).map(|_| 0x06))
                .or_else(|| mf.get("udp").and_then(|v| v.as_str()).map(|_| 0x11))
                .or_else(|| mf.get("icmp").and_then(|v| v.as_str()).map(|_| 0x01))
                .or_else(|| mf.get("icmp6").and_then(|v| v.as_str()).map(|_| 0x3a));

            // Set eth_type from protocol keywords.
            if mf.contains_key("ip") || mf.contains_key("nw_dst") || mf.contains_key("nw_src") {
                intent.eth_type = Some(0x0800);
            } else if mf.contains_key("arp") {
                intent.eth_type = Some(0x0806);
            } else if mf.contains_key("tcp") {
                intent.eth_type = Some(0x0800);
                intent.ip_proto = Some(0x06);
            } else if mf.contains_key("udp") {
                intent.eth_type = Some(0x0800);
                intent.ip_proto = Some(0x11);
            } else if mf.contains_key("icmp") {
                intent.eth_type = Some(0x0800);
                intent.ip_proto = Some(0x01);
            } else if mf.contains_key("icmp6") {
                intent.eth_type = Some(0x86DD);
                intent.ip_proto = Some(0x3a);
            }

            intent.nw_dst = mf
                .get("nw_dst")
                .and_then(|v| v.as_str())
                .and_then(parse_ipv4_with_mask);

            intent.nw_src = mf
                .get("nw_src")
                .and_then(|v| v.as_str())
                .and_then(parse_ipv4_with_mask);

            intent.tp_dst = mf
                .get("tp_dst")
                .and_then(|v| v.as_str())
                .and_then(|s| s.parse().ok())
                .or_else(|| {
                    mf.get("tp_dst")
                        .and_then(|v| v.as_u64())
                        .and_then(|v| u16::try_from(v).ok())
                });

            intent.tp_src = mf
                .get("tp_src")
                .and_then(|v| v.as_str())
                .and_then(|s| s.parse().ok())
                .or_else(|| {
                    mf.get("tp_src")
                        .and_then(|v| v.as_u64())
                        .and_then(|v| u16::try_from(v).ok())
                });

            intent.ct_state = mf
                .get("ct_state")
                .and_then(|v| v.as_str())
                .and_then(parse_ct_state);

            intent.tcp_flags = mf
                .get("tcp_flags")
                .and_then(|v| v.as_str())
                .and_then(parse_tcp_flags);

            intent.dl_src = mf
                .get("dl_src")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string());
        }

        // Parse actions.
        if let Some(actions) = flow.get("actions").and_then(|v| v.as_array()) {
            for action in actions {
                let kind = action.get("type").and_then(|v| v.as_str()).unwrap_or("");
                match kind {
                    "output" => {
                        intent.out_port = action
                            .get("port")
                            .and_then(|v| v.as_str())
                            .map(|s| s.to_string());
                    }
                    "normal" => {
                        intent.action_normal = true;
                    }
                    "drop" => {
                        intent.action_drop = true;
                    }
                    "controller" => {
                        intent.action_controller = action
                            .get("max_len")
                            .and_then(|v| v.as_u64())
                            .and_then(|v| u16::try_from(v).ok())
                            .or(Some(128));
                    }
                    // ct, set_field, load_register, arp_responder etc. are
                    // handled by the rovs-openflow Action enum when needed.
                    // For now, log a warning for unsupported action types.
                    other => {
                        tracing::warn!("unsupported action type '{}' in intent, skipping", other);
                    }
                }
            }
        }

        flows.push(intent);
    }

    Ok(flows)
}

fn parse_hex_u16(s: &str) -> Option<u16> {
    let s = s.strip_prefix("0x").unwrap_or(s);
    u16::from_str_radix(s, 16).ok()
}

fn parse_ipv4_with_mask(s: &str) -> Option<Ipv4Addr> {
    let addr_str = s.split('/').next()?;
    addr_str.parse().ok()
}

/// Parse ct_state string like "+est+trk" into a bitmask.
fn parse_ct_state(s: &str) -> Option<u32> {
    let mut mask = 0u32;
    for token in s.split('+').skip(1) {
        // Skip the leading '+' which produces an empty first token.
        match token {
            "est" => mask |= 0x10,
            "trk" => mask |= 0x20,
            "new" => mask |= 0x08,
            "rel" => mask |= 0x04,
            "inv" => mask |= 0x01,
            "rpl" => mask |= 0x02,
            "nat" => mask |= 0x40,
            _ => {}
        }
    }
    Some(mask)
}

/// Parse tcp_flags string like "+syn-ack" or "0x000" into a value.
fn parse_tcp_flags(s: &str) -> Option<u16> {
    if let Some(hex) = s.strip_prefix("0x") {
        return u16::from_str_radix(hex, 16).ok();
    }
    let mut flags = 0u16;
    for token in s.split('-') {
        let token = token.trim_start_matches('+');
        match token {
            "syn" => flags |= 0x002,
            "ack" => flags |= 0x010,
            "fin" => flags |= 0x001,
            "rst" => flags |= 0x004,
            "psh" => flags |= 0x008,
            "urg" => flags |= 0x020,
            _ => {}
        }
    }
    Some(flags)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("op_network=info".parse()?))
        .init();

    let address_str = std::env::var("OF_CONTROLLER_ADDRESS")
        .unwrap_or_else(|_| "unix:/var/run/openvswitch/ovsbr0.mgmt".to_string());
    let address: Address = address_str
        .parse()
        .with_context(|| format!("parse OF_CONTROLLER_ADDRESS '{}'", address_str))?;

    let priority: u16 = std::env::var("OF_FLOW_PRIORITY")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(100);

    let bridge = std::env::var("OF_BRIDGE").unwrap_or_else(|_| "ovsbr0".to_string());
    let intent_flows = load_intent_flows(&bridge, priority)?;

    if intent_flows.is_empty() {
        anyhow::bail!(
            "No valid schema-owned OpenFlow flows found for bridge {} at {}",
            bridge,
            intent_path_for_bridge(&bridge).display()
        );
    }

    info!(
        "Loaded {} schema-owned OpenFlow flows from plugin intent for bridge {}",
        intent_flows.len(),
        bridge
    );

    // Get port name → ofport mapping from OVSDB.
    let port_map = get_port_map_from_ovsdb(&bridge).await?;
    info!(ports = port_map.len(), "discovered ports from OVSDB");

    // Connect to OVS and install flows.
    let mut conn = VConn::connect(&address)
        .await
        .with_context(|| format!("OF connect to {}", address))?;

    info!(address = %address, "connected to OVS");

    // Clear existing flows.
    let delete_all = rovs_openflow::Flow::delete()
        .table(0xFF)
        .match_fields(Match::new());
    conn.send_flow(&delete_all)
        .await
        .context("delete all flows")?;
    info!("cleared existing flows");

    // Install each intent flow.
    let mut installed = 0u32;
    for intent in &intent_flows {
        match build_flow_from_intent(intent, &port_map) {
            Ok(flow) => match conn.send_flow_sync(&flow).await {
                Ok(()) => {
                    installed += 1;
                    info!(
                        "installed flow: priority={} cookie={:#x}",
                        intent.priority, intent.cookie
                    );
                }
                Err(e) => {
                    tracing::error!(
                        "failed to install flow priority={}: {:#}",
                        intent.priority,
                        e
                    );
                }
            },
            Err(e) => {
                tracing::warn!("skipping flow: {:#}", e);
            }
        }
    }

    info!(installed, "flows installed; entering keepalive loop");

    // Keepalive loop.
    loop {
        let _ = conn.recv_message().await?;
    }
}

/// Build a `rovs_openflow::Flow` from an `IntentFlow`, resolving port names.
fn build_flow_from_intent(
    intent: &IntentFlow,
    port_map: &std::collections::HashMap<String, u32>,
) -> Result<rovs_openflow::Flow> {
    let mut m = Match::new();

    if let Some(ref name) = intent.in_port {
        let port = port_map
            .get(name)
            .ok_or_else(|| anyhow::anyhow!("in_port '{}' not found", name))?;
        m = m.in_port(*port);
    }
    if let Some(t) = intent.eth_type {
        m = m.eth_type(t);
    }
    if let Some(addr) = intent.nw_dst {
        m = m.ipv4_dst(addr, 32);
    }
    if let Some(addr) = intent.nw_src {
        m = m.ipv4_src(addr, 32);
    }
    if let Some(p) = intent.ip_proto {
        m = m.ip_proto(p);
    }
    if let Some(p) = intent.tp_dst {
        m = m.tcp_dst(p);
    }
    if let Some(p) = intent.tp_src {
        m = m.tcp_src(p);
    }
    if let Some(s) = intent.ct_state {
        m = m.ct_state(s);
    }
    if let Some(f) = intent.tcp_flags {
        m.tcp_flags = Some(f);
    }

    // Build actions.
    let mut actions = ActionList::new();

    if let Some(ref name) = intent.out_port {
        if name.eq_ignore_ascii_case("normal") {
            actions = actions.normal();
        } else if name.eq_ignore_ascii_case("controller") {
            actions = actions.controller(intent.action_controller.unwrap_or(128));
        } else {
            let port = port_map
                .get(name)
                .ok_or_else(|| anyhow::anyhow!("out_port '{}' not found", name))?;
            actions = actions.output(OutputPort::Port(*port));
        }
    }
    if intent.action_normal {
        actions = actions.normal();
    }
    if let Some(max_len) = intent.action_controller {
        if intent.out_port.is_none() {
            actions = actions.controller(max_len);
        }
    }
    // action_drop = empty actions = implicit drop.

    let mut f = rovs_openflow::Flow::add()
        .match_fields(m)
        .actions(actions)
        .priority(intent.priority)
        .cookie(intent.cookie)
        .table(intent.table_id);

    if intent.idle_timeout > 0 {
        f = f.idle_timeout(intent.idle_timeout);
    }
    if intent.hard_timeout > 0 {
        f = f.hard_timeout(intent.hard_timeout);
    }

    Ok(f)
}

