/// Add a link-scope IPv4 host route (no gateway, scope link — for OVH-style /32 gateway)
pub async fn add_link_route_v4(ifname: &str, dest: Ipv4Addr, prefix: u8) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;

    // Delete any existing identical route first (idempotent)
    let (conn2, handle2, _) = new_connection()?;
    tokio::spawn(conn2);
    let mut routes = handle2.route().get(IpVersion::V4).execute();
    while let Ok(Some(route)) = routes.try_next().await {
        use netlink_packet_route::route::RouteAttribute;
        let matches_dest = route.attributes.iter().any(|a| {
            if let RouteAttribute::Destination(d) = a {
                format!("{:?}", d).contains(&dest.to_string())
            } else {
                false
            }
        });
        if matches_dest && route.header.destination_prefix_length == prefix {
            let _ = handle2.route().del(route).execute().await;
        }
    }

    let (conn3, handle3, _) = new_connection()?;
    tokio::spawn(conn3);
    handle3
        .route()
        .add()
        .v4()
        .destination_prefix(dest, prefix)
        .output_interface(ifindex)
        .execute()
        .await
        .context(format!("Failed to add link route {}/{}", dest, prefix))?;

    Ok(())
}

