/// Create a veth pair `host_name <-> peer_name`. Idempotent: succeeds if both
/// ends already exist with these names (returns Ok without recreating).
pub async fn create_veth_pair(host_name: &str, peer_name: &str) -> Result<()> {
    if link_exists(host_name).await? && link_exists(peer_name).await? {
        log::info!(
            "veth pair {}<->{} already present, skipping create",
            host_name,
            peer_name
        );
        return Ok(());
    }
    if link_exists(host_name).await? || link_exists(peer_name).await? {
        return Err(anyhow::anyhow!(
            "partial veth pair present: {} or {} exists in isolation",
            host_name,
            peer_name
        ));
    }

    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    // rtnetlink::veth(name, peer_name): `peer_name` is the main message name,
    // `name` is the peer-side name. We want host_name on the host (main) side.
    handle
        .link()
        .add()
        .veth(peer_name.to_string(), host_name.to_string())
        .execute()
        .await
        .with_context(|| format!("create veth {}<->{}", host_name, peer_name))?;
    log::info!("created veth pair {}<->{}", host_name, peer_name);
    Ok(())
}

