/// OVSDB client backed by `rovs-ovsdb`.
///
/// Construct with [`OvsdbClient::new`] (sync) or [`OvsdbClient::connect`]
/// (async, eager connection). The lazy variant connects on first use.
pub struct OvsdbClient {
    inner: Arc<Mutex<Inner>>,
}

impl OvsdbClient {
    /// Create a client that connects lazily on first operation.
    ///
    /// The socket path is auto-detected from `SOCKET_PATHS`.
    pub fn new() -> Self {
        Self {
            inner: Arc::new(Mutex::new(Inner {
                client: None,
                socket_path: resolve_socket_path(),
            })),
        }
    }

    /// Create a client with an explicit socket path (lazy connect).
    pub fn with_socket(path: impl Into<String>) -> Self {
        Self {
            inner: Arc::new(Mutex::new(Inner {
                client: None,
                socket_path: path.into(),
            })),
        }
    }

    /// Connect eagerly and return a ready client.
    pub async fn connect() -> Result<Self> {
        let this = Self::new();
        this.inner.lock().await.ensure_connected().await?;
        Ok(this)
    }

