    pub async fn ensure_initialized(&self) -> Result<()> {
        let mut guard = self.inner.lock().await;
        let client = guard.ensure_connected().await?;

        if !client.is_connected() {
            // Reconnect — the old connection may have dropped.
            guard.client.take();
            guard.ensure_connected().await?;
        }

        // Verify the Open_vSwitch table has content.
        let idl = guard.client.as_ref().unwrap().idl();
        let has_rows = idl.rows("Open_vSwitch").count() > 0;
