    /// Create an OVS bridge. Idempotent — skips if the bridge already exists.
    pub async fn create_bridge(&self, bridge_name: &str) -> Result<()> {
        if self.bridge_exists(bridge_name).await? {
            tracing::info!("Bridge {} already exists, skipping creation", bridge_name);
            return Ok(());
        }

        let mut guard = self.inner.lock().await;
        let client = guard.ensure_connected().await?;

        let mut txn = Transaction::new("Open_vSwitch");
        txn.create_bridge(bridge_name);

        let committed = client.commit(&mut txn).await?;
        if !committed {
            anyhow::bail!(
                "Transaction to create bridge {} was not committed",
                bridge_name
            );
        }

        // Process buffered monitor updates so the IDL reflects the new bridge.
        let _ = client.run().await;

        drop(guard);

        if self.bridge_exists(bridge_name).await? {
            tracing::info!("Bridge {} successfully created and persisted", bridge_name);
            Ok(())
        } else {
            anyhow::bail!(
                "Bridge {} creation failed — not found after commit",
                bridge_name
            )
        }
    }

    /// Add a system port to a bridge (attaches an existing kernel interface).
    pub async fn add_port(&self, bridge_name: &str, port_name: &str) -> Result<()> {
        self.add_port_with_type(bridge_name, port_name, None).await
