    /// Add a port to a bridge with an explicit interface type.
    ///
    /// `port_type` examples: `"internal"`, `"system"`, `"patch"`, `"geneve"`.
    /// When `None`, no `type` field is set on the Interface row.
    pub async fn add_port_with_type(
        &self,
        bridge_name: &str,
        port_name: &str,
        port_type: Option<&str>,
    ) -> Result<()> {
        let mut guard = self.inner.lock().await;
        let client = guard.ensure_connected().await?;

        let mut txn = Transaction::new("Open_vSwitch");
        match port_type {
            Some("system") => {
                txn.add_system_port(bridge_name, port_name);
            }
            Some("internal") => {
                txn.add_internal_port(bridge_name, port_name);
            }
            Some(other) => {
                txn.add_port(bridge_name, port_name, other);
            }
            None => {
                // No type — insert with empty type.
                txn.add_port(bridge_name, port_name, "");
            }
        }

        let committed = client.commit(&mut txn).await?;
        if !committed {
            anyhow::bail!(
                "Transaction to add port {} to bridge {} was not committed",
                port_name,
                bridge_name
            );
        }
        let _ = client.run().await;

        tracing::info!(
            "Port {} (type: {:?}) added to bridge {}",
            port_name,
            port_type,
            bridge_name
        );
        Ok(())
    }

