    pub async fn bridge_exists(&self, bridge_name: &str) -> Result<bool> {
        // Prefer IDL lookup (zero-copy).
        {
            let guard = self.inner.lock().await;
            if let Some(client) = guard.client.as_ref() {
                if client.is_connected() {
                    for row in client.idl().rows("Bridge") {
                        if row.get_string("name") == Some(bridge_name) {
                            return Ok(true);
                        }
                    }
                    return Ok(false);
                }
            }
        }

        // Fallback: select via transaction.
        match self.find_bridge_uuid(bridge_name).await {
            Ok(_) => Ok(true),
            Err(_) => Ok(false),
        }
    }

