        if let Some(rows) = result[0]["rows"].as_array() {
            if let Some(first) = rows.first() {
                if let Some(uuid_arr) = first["_uuid"].as_array() {
                    if uuid_arr.len() == 2 && uuid_arr[0] == "uuid" {
                        return Ok(uuid_arr[1].as_str().unwrap_or_default().to_string());
                    }
                }
            }
        }

        anyhow::bail!("Bridge '{}' not found", bridge_name)
    }

