            .push(IntentFlow::directed(port_a, port_b, priority));
        self.flows
            .push(IntentFlow::directed(port_b, port_a, priority));
        self
    }

    /// Add a single directed flow by port names.
    pub fn add_flow(mut self, in_port: &str, out_port: &str, priority: u16) -> Self {
        self.flows
            .push(IntentFlow::directed(in_port, out_port, priority));
        self
    }

    /// Add a fully-specified intent flow.
    pub fn add_intent_flow(mut self, flow: IntentFlow) -> Self {
        self.flows.push(flow);
        self
    }

    /// Run the controller: connect, discover ports, install flows, keepalive.
    pub async fn run(self) -> Result<()> {
        let mut conn = VConn::connect(&self.address)
            .await
            .with_context(|| format!("OF connect to {}", self.address))?;

        info!(address = %self.address, "OF controller connected");

        // Clear existing flows on the bridge.
        let delete_all = Flow::delete().table(0xFF).match_fields(Match::new());
        conn.send_flow(&delete_all)
            .await
            .context("delete all flows")?;
        info!("cleared existing flows");

        // Resolve port names → ofport numbers via OVSDB.
        let port_map = get_port_map_from_ovsdb("ovsbr0").await?;
        info!(ports = port_map.len(), "discovered ports from OVSDB");

        // Install intent flows.
        let mut installed = 0u32;
        for flow in &self.flows {
            match build_flow(flow, &port_map) {
                Ok(resolved) => match conn.send_flow_sync(&resolved).await {
                    Ok(()) => {
                        installed += 1;
                        info!(
                            "installed flow: priority={} cookie={:#x}",
                            flow.priority, flow.cookie
                        );
                    }
                    Err(e) => {
                        tracing::error!(
                            "failed to install flow priority={}: {:#}",
                            flow.priority,
                            e
                        );
                    }
                },
                Err(e) => {
                    tracing::warn!("skipping flow: {:#}", e);
                }
            }
        }

        info!(installed, "flows installed; entering keepalive loop");

        // Keepalive loop — VConn handles echo reply internally.
        loop {
            let _ = conn.recv_message().await.context("keepalive recv")?;
        }
    }
}

/// Build a `rovs_openflow::Flow` from an `IntentFlow`, resolving port names.
pub fn build_flow(intent: &IntentFlow, port_map: &HashMap<String, u32>) -> Result<Flow> {
    use rovs_openflow::ActionList;

    let mut m = Match::new();

    if let Some(ref name) = intent.in_port {
        let port = port_map
            .get(name)
            .ok_or_else(|| anyhow::anyhow!("in_port '{}' not found", name))?;
        m = m.in_port(*port);
    }
    if let Some(t) = intent.eth_type {
        m = m.eth_type(t);
    }
    if let Some(addr) = intent.nw_dst {
        m = m.ipv4_dst(addr, 32);
    }
    if let Some(addr) = intent.nw_src {
        m = m.ipv4_src(addr, 32);
    }
    if let Some(p) = intent.ip_proto {
        m = m.ip_proto(p);
    }
    if let Some(p) = intent.tp_dst {
        m = m.tcp_dst(p);
    }
    if let Some(p) = intent.tp_src {
        m = m.tcp_src(p);
    }
    if let Some(s) = intent.ct_state {
        m = m.ct_state(s);
    }
    if let Some(f) = intent.tcp_flags {
        m.tcp_flags = Some(f);
    }

    // Build actions using ActionList builder pattern.
    let mut actions = ActionList::new();

    if let Some(ref name) = intent.out_port {
        if name.eq_ignore_ascii_case("normal") {
            actions = actions.normal();
        } else if name.eq_ignore_ascii_case("controller") {
            actions = actions.controller(intent.action_controller.unwrap_or(128));
        } else {
            let port = port_map
                .get(name)
                .ok_or_else(|| anyhow::anyhow!("out_port '{}' not found", name))?;
            actions = actions.output(OutputPort::Port(*port));
        }
    }
    if intent.action_normal {
        actions = actions.normal();
    }
    if let Some(max_len) = intent.action_controller {
        if intent.out_port.is_none()
            || !intent
                .out_port
                .as_deref()
                .unwrap()
                .eq_ignore_ascii_case("controller")
        {
            actions = actions.controller(max_len);
        }
    }
    // action_drop = empty actions = implicit drop.

    let mut f = Flow::add()
        .match_fields(m)
        .actions(actions)
        .priority(intent.priority)
        .cookie(intent.cookie)
        .table(intent.table_id);

    if intent.idle_timeout > 0 {
        f = f.idle_timeout(intent.idle_timeout);
    }
    if intent.hard_timeout > 0 {
        f = f.hard_timeout(intent.hard_timeout);
    }

    Ok(f)
}

/// Query OVSDB for Interface name → ofport mapping and return it.
pub async fn get_port_map_from_ovsdb(_bridge: &str) -> Result<HashMap<String, u32>> {
    use crate::ovsdb::OvsdbClient;
    use simd_json::prelude::*;

    let ovsdb = OvsdbClient::new();
    ovsdb.ensure_initialized().await?;

    let dump = ovsdb.dump_open_vswitch().await?;
    let mut port_map = HashMap::new();

    // Walk the Interface table rows to find name + ofport.
    if let Some(interfaces) = dump.get("Interface").and_then(|v| v.as_array()) {
        for iface in interfaces {
            if let Some(name) = iface.get("name").and_then(|n| n.as_str()) {
                if let Some(ofport) = iface.get("ofport").and_then(|p| p.as_u64()) {
                    port_map.insert(name.to_string(), ofport as u32);
                }
            }
        }
    }

    Ok(port_map)
}

