//!
//! - Loads a pre-compiled BPF ELF (e.g. `xdp_steering.o`).
//! - Picks the program by section name (default `SEC("xdp")`).
//! - Attaches in SKB (generic), DRV (native), or HW (offload) mode.
//!
//! Strictly native: no shell-out to `ip link set xdp`, no `bpftool`.

use anyhow::{anyhow, Context, Result};
use libbpf_rs::{Object, ObjectBuilder, Xdp, XdpFlags};
use std::ffi::{CString, OsStr};
use std::os::fd::AsFd;
use std::os::unix::ffi::OsStrExt;
use std::path::Path;

/// Attach mode for a loaded XDP program.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum XdpMode {
    /// SKB / generic mode (universal, works on every NIC and veth).
    Generic,
    /// Driver / native mode (faster, requires NIC driver XDP support).
    Driver,
    /// Hardware / offload mode (requires NIC offload support).
    Hardware,
}

impl XdpMode {
    fn flags(self) -> XdpFlags {
        match self {
            XdpMode::Generic => XdpFlags::SKB_MODE | XdpFlags::UPDATE_IF_NOEXIST,
            XdpMode::Driver => XdpFlags::DRV_MODE | XdpFlags::UPDATE_IF_NOEXIST,
            XdpMode::Hardware => XdpFlags::HW_MODE | XdpFlags::UPDATE_IF_NOEXIST,
        }
    }

    fn detach_flags(self) -> XdpFlags {
        match self {
            XdpMode::Generic => XdpFlags::SKB_MODE,
            XdpMode::Driver => XdpFlags::DRV_MODE,
            XdpMode::Hardware => XdpFlags::HW_MODE,
        }
    }

    pub fn parse(s: &str) -> Result<Self> {
        match s.to_ascii_lowercase().as_str() {
            "generic" | "xdpgeneric" | "skb" => Ok(Self::Generic),
            "driver" | "native" | "drv" => Ok(Self::Driver),
            "hardware" | "offload" | "hw" => Ok(Self::Hardware),
            other => Err(anyhow!("unknown XDP mode: {}", other)),
        }
    }
}

/// Resolve interface name to kernel ifindex (no shell, no /sys reads).
pub fn ifindex(ifname: &str) -> Result<u32> {
    let cname = CString::new(ifname).context("ifname has interior NUL")?;
    let idx = unsafe { libc::if_nametoindex(cname.as_ptr()) };
    if idx == 0 {
        Err(std::io::Error::last_os_error())
            .with_context(|| format!("if_nametoindex({}) failed", ifname))
    } else {
        Ok(idx)
    }
}

/// Loaded BPF object. Keep alive while you want the program FD valid.
pub struct LoadedXdp {
    obj: Object,
    section: String,
}

/// Open + load a BPF ELF from disk. The returned [`LoadedXdp`] owns the
/// `bpf_object`; programs inside it are loaded into the kernel but not yet
/// attached.
pub fn load(elf_path: &Path, section: &str) -> Result<LoadedXdp> {
    let open = ObjectBuilder::default()
        .open_file(elf_path)
        .with_context(|| format!("bpf_object__open_file({})", elf_path.display()))?;
    let obj = open
        .load()
        .with_context(|| format!("bpf_object__load({})", elf_path.display()))?;
    Ok(LoadedXdp {
        obj,
        section: section.to_string(),
    })
}

impl LoadedXdp {
    /// Attach the program in this object whose ELF section matches `section`
    /// to `ifname` in the requested mode. Idempotent: if a program is already
    /// attached we replace it.
    pub fn attach(&self, ifname: &str, mode: XdpMode) -> Result<()> {
        let want = OsStr::from_bytes(self.section.as_bytes());
        let prog = self
            .obj
            .progs()
            .find(|p| p.section() == want)
            .ok_or_else(|| {
                anyhow!(
                    "no BPF program with SEC(\"{}\") in loaded object",
                    self.section
                )
            })?;

        let idx = ifindex(ifname)?;
        let xdp = Xdp::new(prog.as_fd());

        // Try plain attach first. If a program is already attached, detach + retry.
        match xdp.attach(idx as i32, mode.flags()) {
            Ok(()) => Ok(()),
            Err(_) => {
                let _ = xdp.detach(idx as i32, mode.detach_flags());
                xdp.attach(idx as i32, mode.flags())
                    .with_context(|| format!("XDP attach to {} ({:?}) failed", ifname, mode))
            }
        }
    }
}

/// Detach any XDP program currently attached to `ifname` for the given mode.
pub fn detach(ifname: &str, mode: XdpMode) -> Result<()> {
    let idx = ifindex(ifname)?;
    // We don't have a program fd here; libbpf's bpf_xdp_detach ignores it when
    // simply removing the currently attached program for the mode.
    let cfd = unsafe { std::os::fd::BorrowedFd::borrow_raw(-1) };
    let xdp = Xdp::new(cfd);
    let _ = xdp.detach(idx as i32, mode.detach_flags());
    Ok(())
}
//! Network namespace helpers — enter a container netns and run rtnetlink ops.

use anyhow::{Context, Result};
use std::ffi::CString;

/// Run an async closure inside the network namespace of the given PID.
///
/// Spawns a dedicated OS thread, calls `setns(2)` to enter `/proc/<pid>/ns/net`,
/// builds a single-threaded tokio runtime there, and returns the result.
/// The calling thread's namespace is unaffected.
pub async fn with_netns_pid<F, T>(pid: u32, f: F) -> Result<T>
where
    F: FnOnce() -> Result<T> + Send + 'static,
    T: Send + 'static,
{
    let (tx, rx) = tokio::sync::oneshot::channel::<Result<T>>();

    std::thread::spawn(move || {
        let ns_path = CString::new(format!("/proc/{}/ns/net", pid)).unwrap();

        let fd = unsafe { libc::open(ns_path.as_ptr(), libc::O_RDONLY | libc::O_CLOEXEC) };
        if fd < 0 {
            let _ = tx.send(Err(anyhow::anyhow!(
                "open netns /proc/{}/ns/net: {}",
                pid,
                std::io::Error::last_os_error()
            )));
            return;
        }

        let rc = unsafe { libc::setns(fd, libc::CLONE_NEWNET) };
        unsafe { libc::close(fd) };

        if rc != 0 {
            let _ = tx.send(Err(anyhow::anyhow!(
                "setns pid {}: {}",
                pid,
                std::io::Error::last_os_error()
            )));
            return;
        }

        let _ = tx.send(f());
    });

    rx.await.context("netns thread panicked")?
}

