                if let Ok(true) = client.run().await {
                    let seqno = client.idl().change_seqno();
                    let snapshot = idl_to_value(client.idl());
                    if tx.send(snapshot).await.is_err() {
                        break;
                    }
                    tracing::trace!("Monitor update pushed, seqno={}", seqno);
                }

                // Block until the next server push.
                match client.wait().await {
                    Ok(()) => {
                        let seqno = client.idl().change_seqno();
                        let snapshot = idl_to_value(client.idl());
                        if tx.send(snapshot).await.is_err() {
