                    Err(e) => {
                        tracing::error!("Monitor wait error: {} — reconnecting", e);
                        tokio::time::sleep(std::time::Duration::from_secs(1)).await;
                        // Reconnect.
                        match rovs_ovsdb::Client::connect_with_config(&addr, config.clone()).await {
                            Ok(c) => {
                                client = c;
                                tracing::info!("Monitor reconnected");
                            }
                            Err(re) => {
                                tracing::error!("Monitor reconnect failed: {}", re);
                                tokio::time::sleep(std::time::Duration::from_secs(5)).await;
                            }
                        }
                    }
                }
            }
        });

        Ok(rx)
    }

