    ///
    /// Returns `None` if the client has not connected yet.
    pub async fn idl(&self) -> Option<IdlSnapshot> {
        let guard = self.inner.lock().await;
        guard.client.as_ref().map(|_| IdlSnapshot {
            inner: Arc::clone(&self.inner),
        })
    }

    /// Wait for the next OVSDB update and process it into the IDL.
    ///
    /// Returns the new `change_seqno` after the update.
    pub async fn wait_for_update(&self) -> Result<u64> {
        let mut guard = self.inner.lock().await;
        let client = guard.ensure_connected().await?;
        client.wait().await?;
        Ok(client.idl().change_seqno())
    }
