/// A snapshot of the IDL obtained via [`OvsdbClient::idl`].
///
/// Dereferences to the inner `MutexGuard` so you can call
/// `snapshot.idl().rows("Bridge")` etc.
pub struct IdlSnapshot {
    inner: Arc<Mutex<Inner>>,
}

impl IdlSnapshot {
    /// Read rows from a table in the IDL.
    ///
    /// Acquires the mutex briefly to clone the relevant rows.
    pub async fn rows(&self, table: &str) -> Vec<RowData> {
        let guard = self.inner.lock().await;
        if let Some(client) = guard.client.as_ref() {
            client
                .idl()
                .rows(table)
                .map(|r| RowData {
                    uuid: r.uuid.to_string(),
                    data: row_to_json(r),
                })
                .collect()
        } else {
            Vec::new()
        }
    }
}

/// A single row read from the IDL snapshot.
#[derive(Debug, Clone)]
pub struct RowData {
    /// The row's `_uuid` value.
    pub uuid: String,
    /// The full row as a JSON object.
    pub data: Value,
}

