/// Check a transaction result array for per-operation errors.
fn check_transaction_errors(result: &Value) -> Result<()> {
    if let Some(results) = result.as_array() {
        for (i, op_result) in results.iter().enumerate() {
            if let Some(error) = op_result.get("error") {
                if let Some(error_str) = error.as_str() {
                    let details = op_result
                        .get("details")
                        .and_then(|d| d.as_str())
                        .unwrap_or("no details");
                    anyhow::bail!("OVSDB operation {} failed: {} ({})", i, error_str, details);
                }
            }
        }
    }
    Ok(())
}

/// Convert an `rovs_ovsdb::Row` into a `serde_json::Value::Object`.
///
/// Includes the `_uuid` column as `["uuid", "<hex>"]` for compatibility
/// with the legacy client's OVSDB value format.
fn row_to_json(row: &rovs_ovsdb::Row) -> Value {
    let mut map = serde_json::Map::new();
    // Insert _uuid in the legacy OVSDB format.
    map.insert("_uuid".into(), json!(["uuid", row.uuid.to_string()]));
    for (col, val) in &row.columns {
        map.insert(col.clone(), val.clone());
    }
    Value::Object(map)
}

/// Resolve port names from a "ports" column value using the IDL.
fn resolve_port_names(idl: &rovs_ovsdb::Idl, ports_val: &Value) -> Vec<String> {
    let mut names = Vec::new();
    if let Some(arr) = ports_val.as_array() {
