}

/// Convert the entire IDL to a single JSON value (for monitor_db channel).
fn idl_to_value(idl: &rovs_ovsdb::Idl) -> Value {
    let mut out = serde_json::Map::new();
    if let Some(schema) = idl.schema() {
        for table_name in schema.tables.keys() {
            let rows: Vec<Value> = idl.rows(table_name).map(row_to_json).collect();
            out.insert(table_name.clone(), Value::Array(rows));
        }
    }
    Value::Object(out)
}

/// Sanitize a name for use in OVSDB named-uuid references.
fn sanitize_name(name: &str) -> String {
    name.chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '_' })
        .collect()
}

