/// Commands that must not be executed because they bypass native protocol paths.
pub const FORBIDDEN_NATIVE_BYPASS_COMMANDS: &[(&str, &str)] = &[
    (
        "ovs-vsctl",
        "use OVSDB JSON-RPC or the schema-owned OVS tool path",
    ),
    (
        "ovs-ofctl",
        "use native OpenFlow/Generic Netlink or PluginSchema state",
    ),
    (
        "ovs-dpctl",
        "use Generic Netlink through the native OVS datapath client",
    ),
    ("ovs-appctl", "use the supported native control-plane APIs"),
    ("ovsdb-client", "send raw JSON-RPC to the OVSDB Unix socket"),
];

/// Commands that have native protocol alternatives.
pub const NATIVE_ALTERNATIVES: &[(&str, &str)] = &[
    // Systemd
    (
        "systemctl",
        "Consider using dbus_systemd_* tools for programmatic access",
    ),
    (
        "journalctl",
        "Consider using dbus_systemd_* tools for structured logs",
    ),
    // Network
    (
        "ip",
        "Consider using network_* native tools for structured output",
    ),
    ("nmcli", "Consider using D-Bus NetworkManager interface"),
    // Package managers
    (
        "apt",
        "Consider using packagekit_* tools for progress tracking",
    ),
    ("apt-get", "Consider using packagekit_* tools"),
    ("dnf", "Consider using packagekit_* tools"),
];

/// Get a hard-block reason if a command bypasses required native paths.
pub fn get_forbidden_native_bypass(command: &str) -> Option<(&'static str, &'static str)> {
    let base_cmd = command.split_whitespace().next()?;
    FORBIDDEN_NATIVE_BYPASS_COMMANDS
        .iter()
        .find(|(cmd, _)| *cmd == base_cmd)
        .copied()
}

/// Get a recommendation message if a native alternative exists
pub fn get_native_recommendation(command: &str) -> Option<&'static str> {
    let base_cmd = command.split_whitespace().next()?;
    NATIVE_ALTERNATIVES
        .iter()
        .find(|(cmd, _)| *cmd == base_cmd)
        .map(|(_, msg)| *msg)
}

