//! OVSDB client facade backed by `rovs-ovsdb`.
//!
//! Provides an `OvsdbClient` with the same method names as the legacy
//! hand-rolled JSON-RPC client in `op-network::ovsdb`, but internally uses
//! `rovs_ovsdb::Client` for a persistent connection, in-memory IDL replica,
//! and typed `Transaction` builder.
//!
//! # Architecture
//!
//! - **Persistent connection** — one `rovs_ovsdb::Client` is reused across
//!   calls (vs. the old per-call `UnixStream` reconnect).
//! - **IDL replica** — `client.idl().rows("Bridge")` gives zero-copy reads
//!   of OVSDB state, matching AGENTS.md "1:1 Direct Read" rule.
//! - **Transaction builder** — `rovs_ovsdb::Transaction::create_bridge`,
//!   `add_system_port`, `add_internal_port`, etc. replace hand-built JSON.
//! - **Monitor** — a dedicated background `rovs_ovsdb::Client` calls
//!   `wait()` in a loop and pushes `serde_json::Value` updates into an
//!   `mpsc::Receiver`, preserving the existing `monitor_db()` consumer API.
//!
//! This crate replaces the OVSDB **transport layer only**. It does NOT
//! touch schema validation, plugin registry, DBus mirror, reconciler,
//! orchestrator, audit trail, gRPC, rtnetlink, or container lifecycle.

use anyhow::{Context, Result};
use serde_json::{json, Value};
use std::path::Path;
use std::sync::Arc;
use tokio::sync::Mutex;
use uuid::Uuid;

// Re-export rovs-ovsdb types for advanced callers.
pub use rovs_ovsdb::{ClientConfig, Idl, MonitorVersion, RowRef, Transaction};

/// Default OVSDB Unix socket paths (checked in order).
const SOCKET_PATHS: &[&str] = &[
    "/usr/local/var/run/openvswitch/db.sock",
    "/var/run/openvswitch/db.sock",
    "/run/openvswitch/db.sock",
];

/// Resolve the OVSDB socket path.
///
/// Checks `OVSDB_SOCKET` env var first, then falls back to auto-detecting
/// from `SOCKET_PATHS` by looking for an existing file.
fn resolve_socket_path() -> String {
    if let Ok(path) = std::env::var("OVSDB_SOCKET") {
        return path;
    }
    SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&SOCKET_PATHS[0])
        .to_string()
}

/// Format a socket path as a `rovs-transport` address string.
fn socket_addr(path: &str) -> String {
    format!("unix:{}", path)
}

// ---------------------------------------------------------------------------
// Inner client state (behind Arc<Mutex<>> for lazy async init)
// ---------------------------------------------------------------------------

struct Inner {
    client: Option<rovs_ovsdb::Client>,
    socket_path: String,
}

impl Inner {
    /// Ensure the `rovs_ovsdb::Client` is connected. Idempotent.
    async fn ensure_connected(&mut self) -> Result<&mut rovs_ovsdb::Client> {
        if self.client.is_none() {
            let addr = socket_addr(&self.socket_path);
            tracing::debug!("Connecting to OVSDB at {}", addr);
            let client = rovs_ovsdb::Client::connect(&addr)
                .await
                .context("Failed to connect to OVSDB")?;
            tracing::info!("Connected to OVSDB, IDL state: {:?}", client.idl().state());
            self.client = Some(client);
        }
        Ok(self.client.as_mut().expect("just ensured client is Some"))
    }
}

