    /// Execute a raw transaction on a specific database.
    pub async fn transact_db(&self, db: &str, operations: Value) -> Result<Value> {
        // rovs_ovsdb::Client is bound to one DB at connect time.
        // For a different DB we need a separate connection.
        if db == "Open_vSwitch" {
            return self.transact(operations).await;
