use anyhow::Result;
use op_ovsdb::OvsdbClient;

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    let client = match std::env::var("OVSDB_SOCKET") {
        Ok(path) => OvsdbClient::with_socket(path),
        Err(_) => OvsdbClient::new(),
    };

    let inserted = client.ensure_open_vswitch_root_row().await?;
    if inserted {
        println!("op-ovsdb-init: inserted Open_vSwitch root row");
    } else {
        println!("op-ovsdb-init: Open_vSwitch root row already present");
    }

    Ok(())
}

