/// Rename network interface
pub async fn link_set_name(old_name: &str, new_name: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by current name
    let mut links = handle
        .link()
        .get()
        .match_name(old_name.to_string())
        .execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", old_name))?;

    let ifindex = link.header.index;

    // Set new name
    handle
        .link()
        .set(ifindex)
        .name(new_name.to_string())
        .execute()
        .await
        .context(format!("Failed to rename {} to {}", old_name, new_name))?;

    Ok(())
}

/// Add an IPv6 subnet route to a specific routing table (idempotent).
pub async fn add_route_v6_table(
    ifname: &str,
    subnet: Ipv6Addr,
    prefix: u8,
    table: u32,
) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;

    let (connection2, handle2, _) = new_connection()?;
    tokio::spawn(connection2);
    let result = handle2
        .route()
        .add()
        .v6()
        .table_id(table)
        .destination_prefix(subnet, prefix)
        .output_interface(ifindex)
        .execute()
        .await;
    ignore_eexist(result)
}

/// Add an IPv6 default route to a specific routing table via an uplink interface (idempotent).
pub async fn add_default_route_v6_table(
    ifname: &str,
    gateway: &str,
    metric: u32,
    table: u32,
) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;
    let gw: Ipv6Addr = gateway.parse().context("Invalid IPv6 gateway")?;

    // Remove any existing default in this table on this interface.
    let (connection2, handle2, _) = new_connection()?;
    tokio::spawn(connection2);
    let mut routes = handle2.route().get(IpVersion::V6).execute();
    while let Ok(Some(route)) = routes.try_next().await {
        use netlink_packet_route::route::RouteAttribute;
        let in_table = route.header.table == table as u8
            || route
                .attributes
                .iter()
                .any(|a| matches!(a, RouteAttribute::Table(t) if *t == table));
        if route.header.destination_prefix_length == 0 && in_table {
            let on_iface = route
                .attributes
                .iter()
                .any(|a| matches!(a, RouteAttribute::Oif(i) if *i == ifindex));
            if on_iface {
                let _ = handle2.route().del(route).execute().await;
            }
        }
    }

    let (connection3, handle3, _) = new_connection()?;
    tokio::spawn(connection3);
    handle3
        .route()
        .add()
        .v6()
        .table_id(table)
        .destination_prefix(Ipv6Addr::UNSPECIFIED, 0)
        .gateway(gw)
        .output_interface(ifindex)
        .priority(metric)
        .execute()
        .await
        .context("Failed to add IPv6 default route to table")
}

/// Add an IPv6 policy rule: `from <src>/128 lookup <table>` at given priority (idempotent).
pub async fn add_rule_v6_from(src: Ipv6Addr, table: u32, priority: u32) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let result = handle
        .rule()
        .add()
        .v6()
        .source_prefix(src, 128)
        .table_id(table)
        .action(RuleAction::ToTable)
        .priority(priority)
        .execute()
        .await;
    ignore_eexist(result)
}

/// Enable proxy NDP on an interface by writing to /proc/sys.
pub fn enable_proxy_ndp(ifname: &str) -> Result<()> {
    let path = format!("/proc/sys/net/ipv6/conf/{}/proxy_ndp", ifname);
    std::fs::write(&path, "1\n").with_context(|| format!("Cannot enable proxy_ndp on {}", ifname))
}

/// Add an IPv6 proxy NDP neighbour entry on `ifname` for `addr` (idempotent).
pub async fn add_proxy_ndp_entry(ifname: &str, addr: Ipv6Addr) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;

    let (connection2, handle2, _) = new_connection()?;
    tokio::spawn(connection2);
    let result = handle2
        .neighbours()
        .add(ifindex, IpAddr::V6(addr))
        .flags(vec![NeighbourFlag::Proxy])
        .execute()
        .await;
    ignore_eexist(result)
}

fn ignore_eexist(result: std::result::Result<(), rtnetlink::Error>) -> Result<()> {
    match result {
        Ok(()) => Ok(()),
        Err(rtnetlink::Error::NetlinkError(ref e)) if e.code.map(|c| c.get()) == Some(-17) => {
            Ok(())
        }
        Err(e) => Err(e.into()),
    }
}

