+//! op-grpc-vethpair - native rtnetlink lifecycle for grpc-uplink <-> grpc-phys.
+//!
+//! This replaces the s6 `ip link` and `ip addr replace` shell commands for the
+//! physical Incus handoff link. The peer end is expected to be claimed by Incus
+//! as `nictype=physical parent=grpc-phys name=eth0`.
+
+use anyhow::{bail, Context, Result};
+use op_network::rtnetlink;
+use std::net::Ipv4Addr;
+
+#[derive(Debug, Clone)]
+struct Config {
+    host_end: String,
+    container_end: String,
+    host_addr: Ipv4Cidr,
+    peer_addr: Ipv4Addr,
+    linklocal_addr: Ipv4Cidr,
+}
+
+#[derive(Debug, Clone)]
+struct Ipv4Cidr {
+    addr: Ipv4Addr,
+    prefix: u8,
+}
+
+impl Ipv4Cidr {
+    fn parse(input: &str) -> Result<Self> {
+        let Some((addr, prefix)) = input.split_once('/') else {
+            bail!("expected IPv4 CIDR, got {}", input);
+        };
+        let addr = addr
+            .parse()
+            .with_context(|| format!("invalid IPv4 address in {}", input))?;
+        let prefix = prefix
+            .parse::<u8>()
+            .with_context(|| format!("invalid IPv4 prefix in {}", input))?;
+        if prefix > 32 {
+            bail!("IPv4 prefix must be <= 32 in {}", input);
+        }
+        Ok(Self { addr, prefix })
+    }
+}
+
+fn env_or(key: &str, default: &str) -> String {
+    std::env::var(key).unwrap_or_else(|_| default.to_string())
+}
+
+fn config() -> Result<Config> {
+    Ok(Config {
+        host_end: env_or("HOST_END", "grpc-uplink"),
+        container_end: env_or("CONTAINER_END", "grpc-phys"),
+        host_addr: Ipv4Cidr::parse(&env_or("HOST_ADDR", "10.200.0.2/32"))?,
+        peer_addr: env_or("PEER_ADDR", "10.200.0.1")
+            .parse()
+            .context("invalid PEER_ADDR")?,
+        linklocal_addr: Ipv4Cidr::parse(&env_or("LINKLOCAL_ADDR", "169.254.249.57/16"))?,
+    })
+}
+
+#[tokio::main(flavor = "current_thread")]
+async fn main() -> Result<()> {
+    let cfg = config()?;
+    let command = std::env::args().nth(1).unwrap_or_else(|| "up".to_string());
+
+    match command.as_str() {
+        "up" => up(&cfg).await,
+        "down" => down(&cfg).await,
+        other => bail!("unknown command '{}'; expected up or down", other),
+    }
+}
+
+async fn up(cfg: &Config) -> Result<()> {
+    let host_present = rtnetlink::link_exists(&cfg.host_end).await?;
+    let container_present = rtnetlink::link_exists(&cfg.container_end).await?;
+
+    if !host_present && container_present {
+        eprintln!(
+            "[op-grpc-vethpair] orphan peer present without host end; recreating {} <-> {}",
+            cfg.host_end, cfg.container_end
+        );
+        rtnetlink::delete_link(&cfg.container_end).await?;
+    }
+
+    let host_present = rtnetlink::link_exists(&cfg.host_end).await?;
+    let container_present = rtnetlink::link_exists(&cfg.container_end).await?;
+    if !host_present && !container_present {
+        rtnetlink::create_veth_pair(&cfg.host_end, &cfg.container_end)
+            .await
+            .with_context(|| format!("create {} <-> {}", cfg.host_end, cfg.container_end))?;
+    }
+
+    rtnetlink::link_up(&cfg.host_end)
+        .await
+        .with_context(|| format!("link up {}", cfg.host_end))?;
+
+    if rtnetlink::link_exists(&cfg.container_end).await? {
+        rtnetlink::link_up(&cfg.container_end)
+            .await
+            .with_context(|| format!("link up {}", cfg.container_end))?;
+    }
+
+    rtnetlink::replace_ipv4_address(
+        &cfg.host_end,
+        &cfg.host_addr.addr.to_string(),
+        cfg.host_addr.prefix,
+    )
+    .await
+    .with_context(|| format!("set host address on {}", cfg.host_end))?;
+    rtnetlink::replace_ipv4_address(
+        &cfg.host_end,
+        &cfg.linklocal_addr.addr.to_string(),
+        cfg.linklocal_addr.prefix,
+    )
+    .await
+    .with_context(|| format!("set link-local address on {}", cfg.host_end))?;
+
+    rtnetlink::add_link_route_v4(&cfg.host_end, cfg.peer_addr, 32)
+        .await
+        .with_context(|| format!("route peer {} via {}", cfg.peer_addr, cfg.host_end))?;
+
+    println!(
+        "[op-grpc-vethpair] ready: {} <-> {}",
+        cfg.host_end, cfg.container_end
+    );
+    Ok(())
+}
+
+async fn down(cfg: &Config) -> Result<()> {
+    if rtnetlink::link_exists(&cfg.host_end).await? {
+        rtnetlink::delete_link(&cfg.host_end).await?;
+    } else {
+        rtnetlink::delete_link(&cfg.container_end).await?;
+    }
+    println!(
+        "[op-grpc-vethpair] deleted: {} <-> {}",
+        cfg.host_end, cfg.container_end
+    );
+    Ok(())
+}
