/// Replace IPv6 default route (idempotent: delete existing, then add)
pub async fn add_default_route_v6(ifname: &str, gateway: &str, metric: u32) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;

    let gw: Ipv6Addr = gateway.parse().context("Invalid IPv6 gateway")?;

    // Delete any existing v6 default route on this interface first
    let mut routes = handle.route().get(IpVersion::V6).execute();
    while let Ok(Some(route)) = routes.try_next().await {
        use netlink_packet_route::route::RouteAttribute;
        if route.header.destination_prefix_length == 0 {
            let on_iface = route
                .attributes
                .iter()
                .any(|a| matches!(a, RouteAttribute::Oif(i) if *i == ifindex));
            if on_iface {
                let _ = handle.route().del(route).execute().await;
            }
        }
    }

    let (connection2, handle2, _) = new_connection()?;
    tokio::spawn(connection2);

    handle2
        .route()
        .add()
        .v6()
        .destination_prefix(Ipv6Addr::UNSPECIFIED, 0)
        .gateway(gw)
        .output_interface(ifindex)
        .priority(metric)
        .execute()
        .await
        .context("Failed to add IPv6 default route")?;

    Ok(())
}

/// Delete all IPv4 default routes via a specific interface.
/// Called before enslaving an interface as an OVS uplink so leftover routes
/// don't shadow the default route we later add via ovsbr0-mgmt.
pub async fn flush_default_routes_v4(ifname: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;

    let (conn2, handle2, _) = new_connection()?;
    tokio::spawn(conn2);

    let mut to_del = Vec::new();
    let mut routes = handle2.route().get(IpVersion::V4).execute();
    while let Ok(Some(route)) = routes.try_next().await {
        use netlink_packet_route::route::RouteAttribute;
        if route.header.destination_prefix_length == 0 {
            let on_iface = route
                .attributes
                .iter()
                .any(|a| matches!(a, RouteAttribute::Oif(i) if *i == ifindex));
            if on_iface {
                to_del.push(route);
            }
        }
    }

    let (conn3, handle3, _) = new_connection()?;
    tokio::spawn(conn3);
    for route in to_del {
        let _ = handle3.route().del(route).execute().await;
    }

    Ok(())
}

