    /// Delete a bridge and its associated port/interface rows.
    pub async fn delete_bridge(&self, bridge_name: &str) -> Result<()> {
        let bridge_uuid = self.find_bridge_uuid(bridge_name).await?;

        // Use the Transaction builder's by-name delete.
        let mut guard = self.inner.lock().await;
        let client = guard.ensure_connected().await?;

        let mut txn = Transaction::new("Open_vSwitch");
        txn.delete_bridge(bridge_name);

        // Also remove from Open_vSwitch.bridges set.
        txn.mutate_by_name(
            "Open_vSwitch",
            "",
            vec![json!([
