        if !committed {
            // Try the UUID-based approach as fallback.
            drop(guard);
            return self.delete_bridge_by_uuid(&bridge_uuid).await;
        }
        let _ = client.run().await;

        tracing::info!("Bridge {} deleted", bridge_name);
