        // Fallback: select via transaction.
        let ops = json!([{
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", bridge_name]],
            "columns": ["_uuid"]
        }]);
        let result = self.transact(ops).await?;

        if let Some(rows) = result[0]["rows"].as_array() {
            if let Some(first) = rows.first() {
                if let Some(uuid_arr) = first["_uuid"].as_array() {
