        let ops = json!([{
            "op": "select",
            "table": "Bridge",
            "where": [["_uuid", "==", ["uuid", &bridge_uuid]]],
            "columns": ["ports"]
        }]);
        let result = self.transact(ops).await?;
        let mut port_uuids = Vec::new();
        if let Some(rows) = result[0]["rows"].as_array() {
            if let Some(first) = rows.first() {
                if let Some(ports) = first["ports"].as_array() {
                    if ports.len() == 2 && ports[0] == "set" {
                        if let Some(set) = ports[1].as_array() {
                            for port in set {
                                if let Some(arr) = port.as_array() {
                                    if arr.len() == 2 && arr[0] == "uuid" {
                                        port_uuids
