                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        let mut port_names = Vec::new();
        for pu in &port_uuids {
            let ops = json!([{
                "op": "select",
                "table": "Port",
                "where": [["_uuid", "==", ["uuid", pu]]],
                "columns": ["name"]
            }]);
            let res = self.transact(ops).await?;
            if let Some(rows) = res[0]["rows"].as_array() {
                if let Some(first) = rows.first() {
                    if let Some(name) = first["name"].as_str() {
                        port_names.push(name.to_string());
                    }
                }
            }
        }
        Ok(port_names)
    }

