}

fn env_or(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_string())
}

fn config() -> Result<Config> {
    Ok(Config {
        bridge: env_or("BR", "ovsbr0"),
        uplink: env_or("UPLINK", "eth0"),
        mgmt_addr: Ipv4Cidr::parse(&env_or("MGMT_ADDR", "148.113.204.83/32"))?,
        container_addr: Ipv4Cidr::parse(&env_or("CONTAINER_ADDR", "15.235.37.41/32"))?,
        gateway: env_or("GW", "148.113.204.1")
            .parse()
            .context("invalid GW")?,
        metric: env_or("METRIC", "1002")
            .parse()
            .context("invalid METRIC")?,
    })
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    let cfg = config()?;
    let command = std::env::args().nth(1).unwrap_or_else(|| "up".to_string());

    match command.as_str() {
        "up" => up(&cfg).await,
        "down" => down(&cfg).await,
        other => bail!("unknown command '{}'; expected up or down", other),
    }
}

async fn up(cfg: &Config) -> Result<()> {
    let ovsdb = OvsdbClient::new();
    ovsdb.ensure_initialized().await.context("OVSDB not reachable")?;

    rtnetlink::del_ipv4_address(
        &cfg.uplink,
        &cfg.mgmt_addr.addr.to_string(),
        cfg.mgmt_addr.prefix,
    )
    .await
    .ok();
    rtnetlink::del_ipv4_address(
        &cfg.uplink,
        &cfg.container_addr.addr.to_string(),
        cfg.container_addr.prefix,
    )
    .await
    .ok();

    if ovsdb.bridge_exists(&cfg.bridge).await? {
        ovsdb
            .delete_bridge(&cfg.bridge)
            .await
            .with_context(|| format!("delete bridge {}", cfg.bridge))?;
    }
    ovsdb
        .create_bridge(&cfg.bridge)
        .await
        .with_context(|| format!("create bridge {}", cfg.bridge))?;
    ovsdb
        .set_bridge_property(&cfg.bridge, "datapath_type", "netdev")
        .await
        .with_context(|| format!("set {} datapath_type=netdev", cfg.bridge))?;
    ovsdb
        .add_port_with_type(&cfg.bridge, &cfg.uplink, Some("afxdp"))
        .await
        .with_context(|| format!("add AF_XDP port {} to {}", cfg.uplink, cfg.bridge))?;

    wait_for_link(&cfg.bridge).await?;
    rtnetlink::link_up(&cfg.uplink)
        .await
        .with_context(|| format!("link up {}", cfg.uplink))?;
    rtnetlink::link_up(&cfg.bridge)
        .await
        .with_context(|| format!("link up {}", cfg.bridge))?;
    rtnetlink::flush_addresses(&cfg.uplink)
        .await
        .with_context(|| format!("flush addresses on {}", cfg.uplink))?;
    rtnetlink::replace_ipv4_address(
        &cfg.bridge,
        &cfg.mgmt_addr.addr.to_string(),
        cfg.mgmt_addr.prefix,
    )
    .await
    .with_context(|| format!("set management address on {}", cfg.bridge))?;
    rtnetlink::add_link_route_v4(&cfg.bridge, cfg.gateway, 32)
        .await
        .with_context(|| format!("route gateway {} on {}", cfg.gateway, cfg.bridge))?;
    rtnetlink::add_default_route_v4(&cfg.bridge, &cfg.gateway.to_string(), cfg.metric)
        .await
        .with_context(|| format!("default route via {} on {}", cfg.gateway, cfg.bridge))?;

    println!(
        "[op-ovsbr0-afxdp] {} ready with {}/{}; {}/{} reserved for container",
        cfg.bridge,
        cfg.mgmt_addr.addr,
        cfg.mgmt_addr.prefix,
        cfg.container_addr.addr,
        cfg.container_addr.prefix
    );
    Ok(())
}

async fn down(cfg: &Config) -> Result<()> {
    let ovsdb = OvsdbClient::new();
    ovsdb.ensure_initialized().await.context("OVSDB not reachable")?;

    rtnetlink::del_ipv4_address(
        &cfg.bridge,
        &cfg.mgmt_addr.addr.to_string(),
        cfg.mgmt_addr.prefix,
    )
    .await
    .ok();
    if ovsdb.bridge_exists(&cfg.bridge).await? {
        ovsdb
            .delete_bridge(&cfg.bridge)
            .await
            .with_context(|| format!("delete bridge {}", cfg.bridge))?;
    }
    rtnetlink::link_up(&cfg.uplink)
        .await
        .with_context(|| format!("link up {}", cfg.uplink))?;
    rtnetlink::replace_ipv4_address(
        &cfg.uplink,
        &cfg.mgmt_addr.addr.to_string(),
        cfg.mgmt_addr.prefix,
    )
    .await
    .with_context(|| format!("restore management address on {}", cfg.uplink))?;
    rtnetlink::add_link_route_v4(&cfg.uplink, cfg.gateway, 32)
        .await
        .with_context(|| format!("route gateway {} on {}", cfg.gateway, cfg.uplink))?;
    rtnetlink::add_default_route_v4(&cfg.uplink, &cfg.gateway.to_string(), cfg.metric)
        .await
        .with_context(|| format!("default route via {} on {}", cfg.gateway, cfg.uplink))?;

    println!(
        "[op-ovsbr0-afxdp] {} removed; management restored on {}",
        cfg.bridge, cfg.uplink
    );
    Ok(())
}

async fn wait_for_link(ifname: &str) -> Result<()> {
    for _ in 0..50 {
        if rtnetlink::link_exists(ifname).await? {
            return Ok(());
        }
        sleep(Duration::from_millis(100)).await;
    }
    bail!("interface {} did not appear", ifname)
}

