//! 🟢 🛷 gRPC Bridge Client — Wires op-mcp-proxy to op-grpc-bridge
//!
//! Translates MCP JSON-RPC methods into op-grpc-bridge gRPC service calls
//! (StateSync, PluginService, EventChainService) with Ghostbridge identity
//! headers injected on every request (The Accountability Loop).
//!
//! The proxy reads the current footprint from /dev/shm/plugin_schema.dat
//! (The Sled — 1:1 Direct Read) and the WireGuard pubkey from the
//! environment. Every outbound gRPC call carries:
//!   - x-ghostbridge-footprint  (current hashed footprint from shared memory)
//!   - x-ghostbridge-trace-id   (session trace ID for the Accountability Page)

use anyhow::{Context, Result};
use memmap2::MmapOptions;
use simd_json::prelude::*;
use simd_json::OwnedValue;
use std::fs::File;
use tonic::metadata::MetadataValue;
use tonic::transport::Channel;
use tonic::{Request, Status};
use tracing::{debug, info, warn};
use uuid::Uuid;

/// The Sled layout — must match op-grpc-bridge/src/interceptor.rs exactly.
#[repr(C)]
struct IdentitySled {
    wireguard_pubkey: [u8; 32],
    mutation_index: u64,
    is_valid: bool,
    hashed_footprint: [u8; 32],
}

/// gRPC bridge client that talks to op-grpc-bridge at :50051
/// and injects Ghostbridge headers for every request.
pub struct GrpcBridgeClient {
    channel: Channel,
    trace_id: String,
}

impl GrpcBridgeClient {
    /// Connect to the op-grpc-bridge gRPC server.
    pub async fn connect(addr: &str) -> Result<Self> {
        let channel = Channel::from_shared(addr.to_string())?
            .connect()
            .await
            .context("Failed to connect to op-grpc-bridge")?;

        let trace_id = format!("mcp-proxy-{}", Uuid::new_v4());
        info!("Connected to op-grpc-bridge at {}, trace_id={}", addr, trace_id);

        Ok(Self { channel, trace_id })
    }

    /// Read the current footprint from The Sled (shared memory).
    /// Falls back to a zero-footprint if /dev/shm is unavailable (dev mode).
    fn read_current_footprint() -> String {
        match File::open("/dev/shm/plugin_schema.dat") {
            Ok(file) => {
                let mmap = unsafe { MmapOptions::new().map(&file) };
                match mmap {
                    Ok(mmap) => {
                        let sled_ptr = mmap.as_ptr() as *const IdentitySled;
                        let footprint = unsafe { (*sled_ptr).hashed_footprint };
                        hex::encode(footprint)
                    }
                    Err(e) => {
                        warn!("Mmap failed for plugin_schema.dat: {}", e);
                        "0".repeat(64)
                    }
                }
            }
            Err(_) => {
                debug!("SchemaEngine sled not available at /dev/shm/plugin_schema.dat — using dev footprint");
                "0".repeat(64)
            }
        }
    }

    /// Inject Ghostbridge identity headers into a tonic Request.
    fn inject_headers<T>(&self, mut req: Request<T>) -> Request<T> {
        let footprint = Self::read_current_footprint();
        if let Ok(val) = footprint.parse::<MetadataValue<_>>() {
            req.metadata_mut().insert("x-ghostbridge-footprint", val);
        }
        if let Ok(val) = self.trace_id.parse::<MetadataValue<_>>() {
            req.metadata_mut().insert("x-ghostbridge-trace-id", val);
        }
        req
    }

    /// Handle an MCP JSON-RPC request by routing it to the appropriate
    /// op-grpc-bridge service and returning a JSON-RPC response.
    pub async fn handle_mcp_request(&self, req: &OwnedValue) -> OwnedValue {
        let method = req["method"].as_str().unwrap_or("");
        let id = req.get("id").cloned().unwrap_or_else(OwnedValue::null);

        match method {
            // ── MCP Protocol Surface ──────────────────────────────────
            "initialize" => self.handle_initialize(&id).await,
            "tools/list" => self.handle_tools_list(&id).await,
            "tools/call" => self.handle_tools_call(&id, req).await,

            // ── State Operations ──────────────────────────────────────
            "state/get" | "getState" => self.handle_get_state(&id, req).await,
            "state/mutate" | "mutate" => self.handle_mutate(&id, req).await,

            // ── Plugin Operations ─────────────────────────────────────
            "plugins/list" | "listPlugins" => self.handle_list_plugins(&id).await,
            "plugins/schema" | "getSchema" => self.handle_get_schema(&id, req).await,
            "plugins/call" | "callMethod" => self.handle_call_method(&id, req).await,

            // ── Event Chain ───────────────────────────────────────────
            "events/get" | "getEvents" => self.handle_get_events(&id, req).await,
            "events/verify" | "verifyChain" => self.handle_verify_chain(&id).await,

            _ => {
                warn!("Unknown MCP method forwarded to gRPC: {}", method);
                error_response(&id, -32601, format!("Method not found: {}", method))
            }
        }
    }

